def convert_gk(raw, height=None):
    """raw: EA FC values in the form of sofifa.parse_page (gkdiving, ...), height in cm -> {attribute: value 40-99}"""
    x = [raw.get(f, 60) for f in FEATURES[:-2]] + [height or 190, 1.0]
    return {a: max(40, min(99, int(sum(c * v for c, v in zip(w, x)) + 0.5))) for a, w in COEF.items()}
